INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$f880f910$SATQ$, $SATQ$fdf648c1-f590-4c15-b580-2bbbdeb7df2f$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Advanced Math$SATQ$, $SATQ$P$SATQ$, $SATQ$P.C.$SATQ$, $SATQ$Nonlinear functions$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, NULL, $SATQ$<p style="text-align: left;">The area of a triangle is <math alttext="270"><mn>270</mn>
</math> square centimeters. The length of the base of the triangle is <math alttext="12"><mn>12</mn>
</math> centimeters greater than the height of the triangle. What is the height, in centimeters, of the triangle?</p>$SATQ$, $SATQ$[{"id":"63c48bbd-0f1f-4394-9cc0-027f6e412bb9","content":"<p><math alttext=\"15\"><mn>15</mn>\n</math></p>"},{"id":"a86d3bb3-edb9-4c17-a798-df2fc69bf1de","content":"<p><math alttext=\"18\"><mn>18</mn>\n</math></p>"},{"id":"cfc187d6-8f93-4a3e-85c6-ba0b7ad402fa","content":"<p><math alttext=\"30\"><mn>30</mn>\n</math></p>"},{"id":"368243c6-7768-42ff-9944-6535bc8c907f","content":"<p><math alttext=\"36\"><mn>36</mn>\n</math></p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["a86d3bb3-edb9-4c17-a798-df2fc69bf1de"]$SATQ$::jsonb, $SATQ$<p style="text-align: left;">Choice B is correct. The area, <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="upper A"><mi>A</mi></math>, of a triangle is given by the formula <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="upper A equals one half b h"><mi>A</mi><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mi>b</mi><mi>h</mi></math>, where <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="b"><mi>b</mi></math> represents the length of the base of the triangle and <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="h"><mi>h</mi></math> represents its height. It’s given that the area of a triangle is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="270"><mn>270</mn></math> square centimeters and that the length of the base of this triangle is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="12"><mn>12</mn></math> centimeters greater than the height of the triangle. Let <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="x"><mi>x</mi></math> represent the height, in centimeters, of the triangle. It follows that the length of the base of the triangle can be expressed as <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="x plus 12"><mi>x</mi><mo>+</mo><mn>12</mn></math>. Substituting <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="270"><mn>270</mn></math> for <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="upper A"><mi>A</mi></math>, <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="x"><mi>x</mi></math> for <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="h"><mi>h</mi></math>, and <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="x plus 12"><mi>x</mi><mo>+</mo><mn>12</mn></math> for <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="b"><mi>b</mi></math> in the formula <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="upper A equals one half b h"><mi>A</mi><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mi>b</mi><mi>h</mi></math> yields <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="270 equals one half left parenthesis x plus 12 right parenthesis left parenthesis x right parenthesis"><mn>270</mn><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mo>(</mo><mi>x</mi><mo>+</mo><mn>12</mn><mo>)</mo><mo>(</mo><mi>x</mi><mo>)</mo></math>, or <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="270 equals one half x left parenthesis x plus 12 right parenthesis"><mn>270</mn><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mi>x</mi><mo>(</mo><mi>x</mi><mo>+</mo><mn>12</mn><mo>)</mo></math>. Multiplying both sides of this equation by <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="2"><mn>2</mn></math> yields <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="540 equals x left parenthesis x plus 12 right parenthesis"><mn>540</mn><mo>=</mo><mi>x</mi><mo>(</mo><mi>x</mi><mo>+</mo><mn>12</mn><mo>)</mo></math>. Applying the distributive property on the right-hand side of this equation yields <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="540 equals x squared plus 12 x"><mn>540</mn><mo>=</mo><msup><mi>x</mi><mn>2</mn></msup><mo>+</mo><mn>12</mn><mi>x</mi></math>. Subtracting <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="540"><mn>540</mn></math> from both sides of this equation yields <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="0 equals x squared plus 12 x minus 540"><mn>0</mn><mo>=</mo><msup><mi>x</mi><mn>2</mn></msup><mo>+</mo><mn>12</mn><mi>x</mi><mo>-</mo><mn>540</mn></math>. In factored form, this equation is equivalent to <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="left parenthesis x plus 30 right parenthesis left parenthesis x minus 18 right parenthesis equals 0"><mo>(</mo><mi>x</mi><mo>+</mo><mn>30</mn><mo>)</mo><mo>(</mo><mi>x</mi><mo>-</mo><mn>18</mn><mo>)</mo><mo>=</mo><mn>0</mn></math>. Applying the zero product property, it follows that <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="x plus 30 equals 0"><mi>x</mi><mo>+</mo><mn>30</mn><mo>=</mo><mn>0</mn></math> or <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="x minus 18 equals 0"><mi>x</mi><mo>-</mo><mn>18</mn><mo>=</mo><mn>0</mn></math>. Subtracting <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="30"><mn>30</mn></math> from both sides of the equation <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="x plus 30 equals 0"><mi>x</mi><mo>+</mo><mn>30</mn><mo>=</mo><mn>0</mn></math> yields <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="x equals negative 30"><mi>x</mi><mo>=</mo><mo>-</mo><mn>30</mn></math>. Adding <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="18"><mn>18</mn></math> to both sides of the equation <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="x minus 18 equals 0"><mi>x</mi><mo>-</mo><mn>18</mn><mo>=</mo><mn>0</mn></math> yields <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="x equals 18"><mi>x</mi><mo>=</mo><mn>18</mn></math>. Since <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="x"><mi>x</mi></math> represents the height of the triangle, it must be positive. Therefore, the height, in centimeters, of the triangle is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="18"><mn>18</mn></math>.</p>
<p>Choice A is incorrect and may result from conceptual or calculation errors.</p>
<p>Choice C is incorrect and may result from conceptual or calculation errors.</p>
<p>Choice D is incorrect and may result from conceptual or calculation errors.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"f880f910","external_id":"fdf648c1-f590-4c15-b580-2bbbdeb7df2f","disclosed_item_id":null,"source":"qbank","vaultid":null,"uId":"69340109-ab94-46c5-897a-d72555e06bb4","program":"SAT","test_type":2,"test_type_desc":"Math","primary_class_cd":"P","domain":"Advanced Math","skill_cd":"P.C.","skill_desc":"Nonlinear functions","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":null,"stem":"<p style=\"text-align: left;\">The area of a triangle is <math alttext=\"270\"><mn>270</mn>\n</math> square centimeters. The length of the base of the triangle is <math alttext=\"12\"><mn>12</mn>\n</math> centimeters greater than the height of the triangle. What is the height, in centimeters, of the triangle?</p>","answerOptions":[{"id":"63c48bbd-0f1f-4394-9cc0-027f6e412bb9","content":"<p><math alttext=\"15\"><mn>15</mn>\n</math></p>"},{"id":"a86d3bb3-edb9-4c17-a798-df2fc69bf1de","content":"<p><math alttext=\"18\"><mn>18</mn>\n</math></p>"},{"id":"cfc187d6-8f93-4a3e-85c6-ba0b7ad402fa","content":"<p><math alttext=\"30\"><mn>30</mn>\n</math></p>"},{"id":"368243c6-7768-42ff-9944-6535bc8c907f","content":"<p><math alttext=\"36\"><mn>36</mn>\n</math></p>"}],"keys":["a86d3bb3-edb9-4c17-a798-df2fc69bf1de"],"correct_answer":["B"],"rationale":"<p style=\"text-align: left;\">Choice B is correct. The area, <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"upper A\"><mi>A</mi></math>, of a triangle is given by the formula <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"upper A equals one half b h\"><mi>A</mi><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mi>b</mi><mi>h</mi></math>, where <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"b\"><mi>b</mi></math> represents the length of the base of the triangle and <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"h\"><mi>h</mi></ma